#!/usr/bin/env python3
"""Test installation on generated raw files only; no host block devices."""
from __future__ import annotations

import argparse
import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import time

SIZE = 32 * 1024**3
KEEP_SIZE = 64 * 1024**2


def digest(path: Path) -> str:
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def drive(path: Path, name: str, serial: str) -> list[str]:
    # Paths are generated by TemporaryDirectory, not supplied as block devices.
    return ["-drive", f"if=none,id={name},file={path},format=raw",
            "-device", f"virtio-blk-pci,drive={name},serial={serial}"]


def boot(args, scratch: Path, target: Path, sentinel: Path | None,
         marker: str, label: str, timeout: int) -> None:
    vars_file = scratch / f"{label}.fd"
    shutil.copyfile(args.ovmf_vars, vars_file)
    serial = args.logs / f"{label}.serial.log"
    errors = args.logs / f"{label}.qemu.log"
    accel = "kvm" if os.access("/dev/kvm", os.R_OK | os.W_OK) else "tcg"
    cpu = "host" if accel == "kvm" else "max"
    cmd = ["qemu-system-x86_64", "-machine", "q35", "-accel", accel,
           "-cpu", cpu, "-m", "5120", "-smp", "2", "-nic", "none",
           "-vga", "virtio", "-display", "none", "-monitor", "none",
           "-no-reboot", "-serial", f"file:{serial}",
           "-drive", f"if=pflash,format=raw,readonly=on,file={args.ovmf_code}",
           "-drive", f"if=pflash,format=raw,file={vars_file}"]
    cmd += drive(target, "target", "LZ_INSTALL_TARGET")
    if sentinel is not None:
        cmd += drive(sentinel, "sentinel", "LZ_KEEP_DISK")
        cmd += ["-boot", "order=d", "-cdrom", str(args.iso)]
    else:
        cmd += ["-boot", "order=c"]
    print(f"Starting {label}: {accel}/{cpu}", flush=True)
    with errors.open("wb") as stream:
        proc = subprocess.Popen(cmd, stdout=stream, stderr=stream)
        found = False
        try:
            deadline = time.monotonic() + timeout
            while time.monotonic() < deadline:
                lines = serial.read_bytes().splitlines() if serial.exists() else []
                if marker.encode() in lines:
                    found = True
                    break
                if any(line.startswith(b"LOCALZET_INSTALL_FAILED") for line in lines):
                    break
                if proc.poll() is not None:
                    break
                time.sleep(1)
        finally:
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=15)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait()
    if not found:
        if serial.exists():
            print(serial.read_bytes()[-30000:].decode(errors="replace"), flush=True)
        if errors.exists():
            print(errors.read_text(errors="replace"), flush=True)
        raise RuntimeError(f"{label}: missing {marker}")
    print(f"PASS: {label}: {marker}", flush=True)


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("iso", type=Path)
    p.add_argument("--ovmf-code", type=Path, required=True)
    p.add_argument("--ovmf-vars", type=Path, required=True)
    p.add_argument("--logs", type=Path, required=True)
    args = p.parse_args()
    for attr in ("iso", "ovmf_code", "ovmf_vars"):
        path = getattr(args, attr).resolve(strict=True)
        if not path.is_file():
            p.error(f"{attr} must be a regular file")
        setattr(args, attr, path)
    args.logs = args.logs.resolve()
    args.logs.mkdir(parents=True, exist_ok=False)
    with tempfile.TemporaryDirectory(prefix="lz-install-") as name:
        scratch = Path(name)
        target = scratch / "target.raw"
        sentinel = scratch / "untouched.raw"
        with target.open("xb") as stream:
            stream.truncate(SIZE)
        with sentinel.open("xb") as stream:
            for _ in range(KEEP_SIZE // (1024**2)):
                stream.write(os.urandom(1024**2))
        before = digest(sentinel)
        try:
            boot(args, scratch, target, sentinel,
                 "LOCALZET_INSTALL_COMPLETE", "installation", 1200)
        finally:
            after = digest(sentinel)
            (args.logs / "sentinel.sha256").write_text(
                f"before {before}\nafter  {after}\n"
            )
            if before != after:
                raise RuntimeError("Non-target disk was modified")
        print("PASS: non-target disk SHA-256 unchanged", flush=True)
        # New firmware variables, no installation ISO, no other disk.
        boot(args, scratch, target, None,
             "LOCALZET_INSTALLED_READY", "installed-boot", 480)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
